
  window.FOX_CHARS_IMG={"outlaw": {"n": "روباه خلافکار", "s": "data:image/webp;base64,", "l": "/static/912f12e1151df61341c6dceb5bf8c0acabdb1a477110c5be9d67274ca7768861.webp"}, "army": {"n": "روباه ارتشی", "s": "data:image/webp;base64,", "l": "/static/f7690bcb8db5460c2900ece001f532fa17bb45dc7feb9c588c8de47fb286ec30.webp"}, "mafia": {"n": "روباه مافیا", "s": "data:image/webp;base64,", "l": "/static/b86b94f8beb1e92e77566aa496a8817587826974ec29177134f776e8ac8e7060.webp"}, "boss": {"n": "روباه رئیس", "s": "data:image/webp;base64,", "l": "/static/5bd9eb583930671bc60888a3f49380c9ded59299d7100ec46131986575092cb3.webp"}, "rich": {"n": "روباه پولدار", "s": "data:image/webp;base64,", "l": "/static/b284b0237d2e15046bdea3378c538746458ce271770abd0433394c8267867c6b.webp"}, "lazy": {"n": "روباه لش", "s": "data:image/webp;base64,", "l": "/static/3dd77c79708cfffdefeb374d7596c4485830f1beb720e979dfd8ad7e23f2f974.webp"}, "gang": {"n": "روباه گنگ", "s": "data:image/webp;base64,", "l": "/static/9a6ea7d32b0aad39beeecd87c1cf1f5fcac3919c5c9be209e502a885f985992c.webp"}, "ninja": {"n": "روباه نینجا", "s": "data:image/webp;base64,", "l": "/static/27687a8bd12c564886c1cc74c14cc4871a542de3965254821602e24500ad18f6.webp"}, "space": {"n": "روباه فضایی", "s": "data:image/webp;base64,", "l": "/static/8eaea4405b133be11c321436be2a612deacbda2402cc3b5cd38943a5263b5ce2.webp"}, "detective": {"n": "روباه کارآگاه", "s": "data:image/webp;base64,", "l": "/static/8db7d7787343e6b4f3289545da33eeecb8723536d12f9581033bd6185b53d4d3.webp"}, "nurse": {"n": "روباه پرستار", "s": "data:image/webp;base64,", "l": "/static/eeb662d64f9c3755c0b129070e81d73b11741215f626840bbaecb2ec0edbca38.webp"}, "army_girl": {"n": "روباه ارتشی دخترونه", "s": "data:image/webp;base64,", "l": "/static/b5076e1aec904c19d4ffb5f37546161a2fded95380649248f919ef42868704ec.webp"}, "casual_girl": {"n": "روباه با لباس روز", "s": "data:image/webp;base64,", "l": "/static/485a99ae85378cc356f51ac38eee96d3a8eb34d3fc9b4d5fe67a79b7bdd82592.webp"}, "pink_pony": {"n": "روباه با لباس صورتی", "s": "data:image/webp;base64,", "l": "/static/71c353f29d6260389d68909448e7714e00af09371c742479a6292bb5373425d7.webp"}, "achaemenid_girl": {"n": "روباه هخامنشی دخترونه", "s": "data:image/webp;base64,", "l": "/static/b3173a0b9f8e1aad7b1e104157b1cbbfe1da896903a0ebd77615d87b29389e19.webp"}, "boss_girl": {"n": "روباه رئیس دخترونه", "s": "data:image/webp;base64,", "l": "/static/c080afafab252cf9d659e33e1d5b4c9ddfc8eff5ee3f61f7defac123f8ae43e5.webp"}, "rich_girl": {"n": "روباه پولدار دخترونه", "s": "data:image/webp;base64,", "l": "/static/1473135f927ae00faa0dc617fbcded17dbf56898c164ec5aadee5a30070c41c0.webp"}, "king": {"n": "روباه شاه", "s": "data:image/webp;base64,", "l": "/static/ed93bb2a0725fdbbc2352dc87b40cdf603a6129862a7c0c51cf2e97b6ac68687.webp"}, "simple": {"n": "روباه ساده", "s": "data:image/webp;base64,", "l": "/static/cc79c134d5d90e8bff2f365e7cc946798f5277b70a40472a3e310f9fb17f0410.webp"}, "persian": {"n": "روباه با لباس ایرانی", "s": "data:image/webp;base64,", "l": "/static/b7ecd0ee528432da7ce72906a2067653f8ee5b1125cfb715b3849eab24831211.webp"}, "achaemenid_boy": {"n": "روباه هخامنشی پسرونه", "s": "data:image/webp;base64,", "l": "/static/58bdad0bcc8575f0f1366577a8dfd5c3aa8bd407715882050b646573eb5bb4b6.webp"}};
  (function(){
    try{
      if(typeof window!=='undefined'&&window.FOX_CHARS_IMG){
        var preloaded={};
        Object.keys(window.FOX_CHARS_IMG).forEach(function(k){
          var src=window.FOX_CHARS_IMG[k]&&window.FOX_CHARS_IMG[k].s;
          if(src&&!preloaded[src]){
            preloaded[src]=true;
            var im=new Image();
            im.decoding='async';
            im.src=src;
          }
        });
      }
    }catch(e){}
  })();

  (function(){
    'use strict';
    var FA_DIGITS='۰۱۲۳۴۵۶۷۸۹';
    function faNum(n){ return String(n==null?0:n).replace(/[0-9]/g, function(d){ return FA_DIGITS[+d]; }); }
    function fxEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }
    window.__fxEsc=fxEsc;
    var COIN_SVG='<svg width="14" height="14" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="#f5a623"/><circle cx="12" cy="12" r="6.5" fill="none" stroke="#fff" stroke-width="2"/></svg>';
    var CATALOG=[];
    var ME={coins:null,owned:[],active:''},walletReady=false;
    function applyShopWallet(w){if(!w||!window.FoxWallet)return;var latest=window.FoxWallet.apply(w)||window.FoxWallet.state;if(!latest)return;ME={coins:latest.coins,owned:latest.owned,active:latest.active};walletReady=true;setBalance(ME.coins);renderGrid();}
    window.addEventListener('fox-wallet-change',function(e){ME={coins:e.detail.coins,owned:e.detail.owned,active:e.detail.active};walletReady=true;setBalance(ME.coins);renderGrid();});
    window.addEventListener('fox-wallet-reset',function(){ME={coins:null,owned:[],active:''};walletReady=false;setBalance(null);renderGrid();});
    var busyId='';
    function charImg(id, big){
      try{
        var o=window.FOX_CHARS_IMG&&window.FOX_CHARS_IMG[id];
        if(o) return big?o.l:o.s;
      }catch(e){}
      return '';
    }
    function charName(id){
      try{
        var o=window.FOX_CHARS_IMG&&window.FOX_CHARS_IMG[id];
        if(o&&o.n) return o.n;
      }catch(e){}
      return 'کاراکتر روباه';
    }
    window.charBadgeHtml=function(id){
      try{
        if(!id||!window.FOX_CHARS_IMG||!window.FOX_CHARS_IMG[id]) return '';
        var nm=fxEsc(charName(id));
        return '<span class="fox-char-badge"><img class="fx-'+id+'" src="'+window.FOX_CHARS_IMG[id].s+'" alt="'+nm+'" title="'+nm+'" width="20" height="20" decoding="async" fetchpriority="high"/></span>';
      }catch(e){ return ''; }
    };
    window.charOfPhone=function(phone){return window.foxIdentityCharacter?window.foxIdentityCharacter(phone):'';};
    window.charBadgeForPhone=function(phone, name, explicit){
      return window.charBadgeHtml(window.charOfPhone(phone, name, explicit));
    };
    window.UserNameWithCharacter=function(displayName, phone, lookupName, verified, char){
      var labelKind=String(displayName||'').charAt(0)==='@'?'username':'name';var profile=window.FoxProfile&&window.FoxProfile.get(phone);if(profile)displayName=labelKind==='username'?(profile.username?'@'+profile.username:''):profile.name;
      var esc=(typeof escapeHtml==='function')?escapeHtml:fxEsc;
      var vb=(typeof badgeForPhone==='function')?badgeForPhone(phone,lookupName,verified):'';
      return '<span class="fox-user-label" data-fox-label-kind="'+labelKind+'" data-fox-name-phone="'+esc(phone||'')+'">'+esc(displayName)+vb+window.charBadgeForPhone(phone,lookupName,char)+'</span>';
    };
    window.applyCharToName=function(el,user){
      if(!el)return;var phone=user&&typeof user==='object'?user.phone:'';
      el.setAttribute('data-fox-name-phone',phone||'');
      el.querySelectorAll('.fox-char-badge').forEach(function(b){b.remove();});
      var id=window.charOfPhone(phone);if(id)el.insertAdjacentHTML('beforeend',window.charBadgeHtml(id));
    };
    function auth(){
      try{
        var u=(typeof currentUser!=='undefined'&&currentUser)?currentUser:JSON.parse(localStorage.getItem('fox_user')||'null');
        var t=localStorage.getItem('fox_session')||'';
        if(u&&u.phone) return {phone:u.phone,token:t};
      }catch(e){}
      return null;
    }
    function toast(msg){
      var el=document.getElementById('charsToast');
      if(!el) return;
      el.textContent=msg;
      el.classList.add('show');
      clearTimeout(el._to);
      el._to=setTimeout(function(){ el.classList.remove('show'); },2600);
    }
    function setBalance(c){
      var el=document.getElementById('charsCoins');
      if(el) el.textContent=typeof c==='number'?faNum(c):'…';
    }
    function openCharsPanel(){
      var ov=document.getElementById('charsOverlay');
      if(!ov) return;
      ov.classList.add('open');
      ov.setAttribute('aria-hidden','false');
      var c=document.getElementById('charsClose');
      if(c){ try{ c.focus(); }catch(e){} }
      loadShop();
    }
    function closeCharsPanel(){
      var ov=document.getElementById('charsOverlay');
      if(!ov) return;
      ov.classList.remove('open');
      ov.setAttribute('aria-hidden','true');
    }
    window.openCharsPanel=openCharsPanel;
    window.closeCharsPanel=closeCharsPanel;
    function loadShop(){
      var a=auth();
      var grid=document.getElementById('charsGrid');
      if(grid) grid.innerHTML='<div class="chars-loading">در حال بارگذاری کاراکترها…</div>';
      fetch('/api/chars').then(function(r){ return r.json(); }).then(function(cat){
        if(cat&&cat.ok&&cat.chars&&cat.chars.length) CATALOG=cat.chars;
        renderGrid();
      }).catch(function(){
        renderGrid();
      });
      if(window.FoxWallet)window.FoxWallet.refresh().then(function(w){if(w)applyShopWallet(w);});
    }

    var FEMALE_CHAR_IDS = ['nurse', 'army_girl', 'casual_girl', 'pink_pony', 'achaemenid_girl', 'boss_girl', 'rich_girl'];
    var currentCatFilter = 'all';

    function updateProfileCharWidget(){
      try{
        var u = (typeof currentUser!=='undefined'&&currentUser)?currentUser:JSON.parse(localStorage.getItem('fox_user')||'null');
        var aid = (ME&&ME.active)?ME.active:(u&&u.activeCharacterId?u.activeCharacterId:'');
        var pImg = document.getElementById('profileCharImg');
        var pPh = document.getElementById('profileCharPlaceholder');
        var pNm = document.getElementById('profileCharName');
        if(pNm){
          if(aid && window.FOX_CHARS_IMG && window.FOX_CHARS_IMG[aid]){
            pNm.textContent = window.FOX_CHARS_IMG[aid].n;
            if(pImg){ pImg.src = window.FOX_CHARS_IMG[aid].s; pImg.style.display = 'block'; }
            if(pPh) pPh.style.display = 'none';
          } else {
            pNm.textContent = 'بدون کاراکتر (انتخاب کنید)';
            if(pImg) pImg.style.display = 'none';
            if(pPh) pPh.style.display = 'block';
          }
        }
      }catch(e){}
    }
    window.updateProfileCharWidget = updateProfileCharWidget;

    function renderGrid(){
      updateProfileCharWidget();
      var grid=document.getElementById('charsGrid');
      if(!grid) return;
      grid.innerHTML='';
      var noneBtn=document.getElementById('charsNoneBtn');
      if(noneBtn){
        noneBtn.classList.toggle('on', !ME.active);
        noneBtn.disabled=!walletReady||(busyId==='__none');
        noneBtn.textContent=(!ME.active?'بدون کاراکتر ✓':'بدون کاراکتر');
      }
      if(!CATALOG.length){
        grid.innerHTML='<div class="chars-loading">خطا در بارگذاری کاراکترها. پنل را ببند و دوباره باز کن</div>';
        return;
      }
      var filteredCatalog = CATALOG.filter(function(c){
        if(currentCatFilter === 'female') return FEMALE_CHAR_IDS.indexOf(c.id) >= 0;
        if(currentCatFilter === 'male') return FEMALE_CHAR_IDS.indexOf(c.id) < 0;
        return true;
      });
      filteredCatalog.forEach(function(c){
        if(!window.FOX_CHARS_IMG||!window.FOX_CHARS_IMG[c.id]) return;
        var owned=ME.owned.indexOf(c.id)>=0;
        var isActive=ME.active===c.id;
        var busy=!walletReady||(busyId===c.id);
        var card=document.createElement('div');
        card.className='char-card'+(isActive?' active':'');
        card.setAttribute('role','listitem');
        var tag=isActive?'<span class="char-active-tag">فعال است</span>':'';
        var btn;
        if(isActive){
          btn='<button type="button" class="char-btn is-active" disabled>فعال است ✓</button>';
        } else if(owned){
          btn='<button type="button" class="char-btn activate" data-act="activate" data-id="'+c.id+'"'+(busy?' disabled':'')+'>'+(busy?'در حال فعال‌سازی…':'فعال کردن')+'</button>';
        } else {
          btn='<button type="button" class="char-btn buy" data-act="buy" data-id="'+c.id+'"'+(busy?' disabled':'')+'>'+(busy?'در حال خرید…':'خرید')+'</button>';
        }
        var instantThumb = (window.FOX_CHARS_IMG && window.FOX_CHARS_IMG[c.id]) ? window.FOX_CHARS_IMG[c.id].s : charImg(c.id, false);
        var hdUrl = charImg(c.id, true);
        card.innerHTML=tag
          +'<div class="char-preview"><img class="fx-'+c.id+'" src="'+instantThumb+'" data-hd="'+hdUrl+'" alt="'+fxEsc(c.name)+'" width="86" height="86" decoding="async" fetchpriority="high"/></div>'
          +'<div class="char-name">'+fxEsc(c.name)+'</div>'
          +'<div class="char-price">'+COIN_SVG+'<span>'+faNum(c.price)+' سکه</span></div>'
          +btn;
        grid.appendChild(card);
        // Progressive upgrade to 256x256 large image
        (function(cCard, cId){
          var hdUrl = charImg(cId, true);
          if(!hdUrl) return;
          var hi = new Image();
          hi.decoding = 'async';
          hi.src = hdUrl;
          hi.onload = function(){
            var imgEl = cCard.querySelector('.char-preview img');
            if(imgEl && imgEl.getAttribute('data-hd') === hdUrl){
              imgEl.src = hdUrl;
            }
          };
        })(card, c.id);
      });

      // Warm up CacheStorage in background
      try{
        if(typeof window!=='undefined' && window.caches){
          caches.open('fox-chars-cache').then(function(cache){
            CATALOG.forEach(function(item){
              var u = charImg(item.id, true);
              if(u && u.startsWith('/static/')){
                cache.match(u).then(function(has){ if(!has) cache.add(u).catch(function(){}); });
              }
            });
          }).catch(function(){});
        }
      }catch(e){}
    }
    function buyChar(id){
      var a=auth();
      if(!a){ toast('برای خرید کاراکتر اول وارد حسابت شو'); return; }
      busyId=id;
      renderGrid();
      fetch('/api/chars/buy',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({phone:a.phone,token:a.token,id:id})})
      .then(function(r){ return r.json(); })
      .then(function(j){
        busyId='';
        if(j&&j.ok){
          applyShopWallet(j.wallet);
          setBalance(ME.coins);
          renderGrid();
          try{ if(typeof window.refreshFoxWallet==='function') window.refreshFoxWallet(); }catch(e){}
          toast('کاراکتر خریداری شد! حالا فعالش کن');
        } else if(j&&j.error==='coins'){
          if(j.wallet)applyShopWallet(j.wallet);
          if(j.owned) ME.owned=j.owned;
          renderGrid();
          toast(j.message||'سکه روباه کافی نیست');
        } else if(j&&j.error==='owned'){
          if(j.owned) ME.owned=j.owned;
          renderGrid();
          toast(j.message||'این کاراکتر را قبلاً خریدی');
        } else {
          renderGrid();
          toast((j&&j.message)||'خرید ناموفق بود');
        }
      }).catch(function(){
        busyId='';
        renderGrid();
        toast('خطای شبکه. دوباره تلاش کن');
      });
    }
    function activateChar(id){
      var a=auth();
      if(!a){ toast('برای خرید کاراکتر اول وارد حسابت شو'); return; }
      busyId=id||'__none';
      renderGrid();
      fetch('/api/chars/activate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({phone:a.phone,token:a.token,id:id})})
      .then(function(r){ return r.json(); })
      .then(function(j){
        busyId='';
        if(j&&j.ok){
          applyShopWallet(j.wallet);
          setBalance(ME.coins);
          syncSelf(ME.active);
          renderGrid();
          toast(id?'کاراکتر فعال شد':'کاراکتر غیرفعال شد');
        } else if(j&&j.error==='notowned'){
          if(j.owned) ME.owned=j.owned;
          renderGrid();
          toast(j.message||'این کاراکتر را خریداری نکردی');
        } else {
          renderGrid();
          toast((j&&j.message)||'فعال‌سازی ناموفق بود');
        }
      }).catch(function(){
        busyId='';
        renderGrid();
        toast('خطای شبکه. دوباره تلاش کن');
      });
    }
    function syncSelf(activeId){refreshCharNames();}
    function refreshCharNames(){
      try{ if(typeof updateMembers==='function') updateMembers(); }catch(e){}
      try{ if(typeof renderDMList==='function') renderDMList(); }catch(e){}
      try{
        var ml=document.getElementById('membersModal');
        if(ml&&ml.classList.contains('show')&&(typeof renderMembersList==='function')&&(typeof lastUsers!=='undefined')) renderMembersList(lastUsers);
      }catch(e){}
      try{
        var sn=document.getElementById('setName');
        if(sn&&(typeof currentUser!=='undefined')&&currentUser){
          sn.textContent=currentUser.name||'بدون نام';
          if(currentUser.verified&&(typeof applyVerifiedToName==='function')) applyVerifiedToName(sn, currentUser);
          window.applyCharToName(sn, currentUser);
        }
      }catch(e){}
      try{
        var so=document.getElementById('searchOv');
        var hi=document.getElementById('homeSearch');
        if(so&&so.classList.contains('show')&&hi&&(typeof hsFilter==='function')) hsFilter(hi.value);
      }catch(e){}
      try{
        var upm=document.getElementById('upModal'); if(upm&&upm.classList.contains('show')&&(typeof upTarget!=='undefined')&&upTarget&&(typeof currentUser!=='undefined')&&currentUser&&upTarget.phone===currentUser.phone&&(typeof renderUserProfile==='function')&&(typeof userFromMsg==='function')){
          var uu=userFromMsg({phone:currentUser.phone});
          if(uu) renderUserProfile(uu);
        }
      }catch(e){}
    }
    (function init(){
      var ov=document.getElementById('charsOverlay');
      if(!ov) return;
      var closeBtn=document.getElementById('charsClose');
      if(closeBtn) closeBtn.addEventListener('click', closeCharsPanel);
      ov.addEventListener('click', function(e){ if(e.target===ov) closeCharsPanel(); });
      document.addEventListener('keydown', function(e){
        if((e.key==='Escape'||e.key==='Esc')&&ov.classList.contains('open')) closeCharsPanel();
      });
      var grid=document.getElementById('charsGrid');
      if(grid) grid.addEventListener('click', function(e){
        var b=e.target?(e.target.closest?e.target.closest('button[data-act]'):null):null;
        if(!b||b.disabled) return;
        var id=b.getAttribute('data-id');
        if(b.getAttribute('data-act')==='buy') buyChar(id);
        else activateChar(id);
      });
      var noneBtn=document.getElementById('charsNoneBtn');
      
      // Wire category tabs
      var tabBtns = document.querySelectorAll('#charsTabs .chars-tab-btn');
      tabBtns.forEach(function(btn){
        btn.addEventListener('click', function(){
          tabBtns.forEach(function(b){ b.classList.remove('on'); });
          btn.classList.add('on');
          currentCatFilter = btn.getAttribute('data-cat') || 'all';
          renderGrid();
        });
      });

      // Wire direct store buttons from app views
      ['profileCharBox', 'openCharsFromProfile'].forEach(function(id){
        var el = document.getElementById(id);
        if(el) el.addEventListener('click', function(e){
          e.preventDefault();
          openCharsPanel();
        });
      });
      var gmChars = document.getElementById('gmCharsShop');
      if(gmChars) gmChars.addEventListener('click', function(e){
        e.preventDefault();
        var gd = document.getElementById('groupDrawer');
        var go = document.getElementById('groupOverlay');
        if(gd) gd.classList.remove('show');
        if(go) go.classList.remove('show');
        openCharsPanel();
      });

      if(noneBtn) noneBtn.addEventListener('click', function(){
        if(noneBtn.disabled) return;
        activateChar('');
      });
      try{
        var cards=document.querySelectorAll('#planOverlay .plan-card');
        for(var i=0;i<cards.length;i++){
          var t=cards[i].textContent||'';
          if(t.indexOf('خرید کاراکتر')!==-1){
            cards[i].id='btnPlanChars';
            var sb=cards[i].querySelector('.plan-soon');
            if(sb) sb.remove();
            cards[i].addEventListener('click', function(e){
              e.preventDefault();
              if(typeof window.closePlanPanel==='function') window.closePlanPanel();
              else { var po=document.getElementById('planOverlay'); if(po) po.classList.remove('open'); }
              openCharsPanel();
            });
          }
        }
      }catch(e){}
    })();
  })();
  